let store = flow.get("agg_store") || {};
let WINDOW = 1000; // 1 second

// ensure array
let data = msg.payload;
if (!Array.isArray(data)) data = [data];

// ===== STORE DATA =====
data.forEach(p => {

    let tag = p.tag_mac;
    let timeBucket = Math.floor(p.ts / WINDOW) * WINDOW;

    if (!store[tag]) store[tag] = {};
    if (!store[tag][timeBucket]) store[tag][timeBucket] = [];


    store[tag][timeBucket].push({
        anchor_id: p.anchor_id,
        x: p.x,
        y: p.y,
        rssi: p.rssi,
        source: p.source
    });
});

// ===== CLEANUP + OUTPUT =====
let now = Date.now();
let output = [];

Object.keys(store).forEach(tag => {

    Object.keys(store[tag]).forEach(t => {

        let tNum = parseInt(t, 10);

        if (!isNaN(tNum) && now - tNum > WINDOW) {

            let anchors = store[tag][t];

            if (anchors.length >= 1) {
                output.push({
                    tag_mac: tag,
                    ts: tNum,
                    anchors: anchors
                });
            }

            delete store[tag][t];
        }

    });

});


flow.set("agg_store", store);

if (output.length === 0) return null;

msg.payload = output;
return msg;

