let results = [];

// -------- MKGW3 (JSON) --------
if (msg.payload && typeof msg.payload === "object" && Array.isArray(msg.payload.data)) {

    let gateway_mac = msg.topic.split("/")[2].toLowerCase();

    msg.payload.data.forEach(d => {
        if (!d.mac || d.rssi === undefined) return;

        results.push({
            gateway_mac,
            tag_mac: d.mac.toLowerCase().replace(/:/g, ""),
            rssi: d.rssi,
            ts: Date.now()
        });
    });
}

// -------- MKGW4 (BUFFER) --------
else if (Buffer.isBuffer(msg.payload)) {

    const buf = msg.payload;

    if (buf.readUInt8(0) !== 0xEF) return null;

    const gateway_mac = buf.toString('hex', 3, 9).toLowerCase();
    const length = buf.readUInt16BE(9);
    const data = buf.subarray(11, 11 + length);

    let i = 0;

    while (i < data.length) {

        let len = data.readUInt16BE(i + 1);
        let value = data.subarray(i + 3, i + 3 + len);

        if (len >= 7) {
            results.push({
                gateway_mac,
                tag_mac: value.subarray(0, 6).toString('hex'),
                rssi: value.readInt8(6),
                ts: Date.now()
            });
        }

        i += (3 + len);
    }
}

// -------- SAFETY --------
else {
    return null;
}

if (!results.length) return null;

msg.payload = results;
return msg;

const buffer = msg.payload;
if (buffer.readUInt8(0) === 0xef) {
    const code = buffer.readUInt16BE(1);

    const typeMap = {
        0x3004: "device_status",
        0x3006: "firmware_ota_result",
        0x3010: "power_disconnect_alarm",
        0x3011: "low_battery_alarm",
        0x3014: "restore_factory_default",
        0x3032: "mqtt_certificate_download_result",
        0x3089: "gnss",
        0x30a0: "ble",
        0x30b1: "buffered_gnss",
        0x30b2: "buffered_ble",
        0x30b3: "buffered_data"
    };

    const mac_addr = buffer.subarray(3, 9);

    msg.payload = {
        gateway: mac_addr.toString('hex'),  
        msg_type: typeMap[code] || "unknown",
        msg_data: buffer.subarray(9)
    };

    return msg;
}

return null;

const TAGS = {
  "fc0e55cbcc75": "T1",
  "f47f5bcc9fed": "T2",
