return msg;

const beaconTypes = {
    0: "iBeacon", 
	1: "Eddystone-UID", 
	2: "Eddystone-URL", 
	3: "Eddystone-TLM",
    4: "BXP-Deviceinfo", 
	5: "BXP-ACC", 
	6: "BXP-TH", 
	7: "BXP-Button",
    8: "BXP-Tag", 
	9: "PIR", 
	10: "Other", 
	11: "TOF"
};

if (!msg.payload.msg_data) {
    return null;
}

const adv_len = msg.payload.msg_data.readUInt16BE(0);
const ble_adv = msg.payload.msg_data.subarray(2, 2 + adv_len);

let array_beacon = [];

try {

    let type = 0;
    let beacon = { gateway: msg.payload.gateway };
    let cursor = 0;

    while (cursor < ble_adv.length) {
        const flag = ble_adv.readUInt8(cursor);
        cursor += 1

        if (flag == 0x0 && cursor > 1){
            array_beacon.push(beacon);
            beacon = { gateway: msg.payload.gateway };
        }

        const segment_len = ble_adv.readUInt16BE(cursor);
        cursor += 2;
        const end_cursor = cursor + segment_len;

        if (end_cursor > ble_adv.length) break;

        switch (flag) {
            case 0x00:
                type = ble_adv.readUInt8(cursor);
                beacon.type = beaconTypes[type] || "unknown";
                break;
            case 0x01:
                beacon.mac = ble_adv.subarray(cursor, end_cursor).toString('hex');
                break;
            case 0x02:
                beacon.connectable = ble_adv.readUInt8(cursor);
                break;
            case 0x03:
                beacon.timestamp = ble_adv.readUInt32BE(cursor);
                break;
            case 0x04:
                beacon.rssi = ble_adv.readInt8(cursor);
                break;
			case 0x5:
                beacon.raw_data = ble_adv.subarray(cursor, end_cursor);
                break;
            case 0x10:
                beacon.accelerometer = {
                    x: ble_adv.readInt16BE(cursor) / 16,
                    y: ble_adv.readInt16BE(cursor + 2) / 16, 
                    z: ble_adv.readInt16BE(cursor + 4) / 16
                }
                break;
        }

        cursor = end_cursor;
    }
    array_beacon.push(beacon);

    msg.payload = array_beacon;

} catch (error) {
    msg.error = error.message;
    node.error("Parsing error: " + error.message);
}

return msg;

